import React from 'react';
import { FaLaptopCode, FaRobot, FaServer} from "react-icons/fa";
import { BsPeople } from "react-icons/bs";

const skillCategories = [
  {
    title: "AI & ML Expertise",
    icon: <FaRobot />,
    skills: ["LLMs", "RAG", "ChatBots", "NLP", "TensorFlow", "PyTorch"],
    color: "bg-teal-500",
  },
  {
    title: "Development",
    icon: <FaLaptopCode />,
    skills: ["Python", "FastAPI", "React", "Vue", "Vector DBs"],
    color: "bg-orange-400",
  },
  {
    title: "DevOps & Cloud",
    icon: <FaServer />,
    skills: ["Docker", "Kubernetes", "AWS", "CI/CD", "Linux"],
    color: "bg-yellow-400",
  },
  {
    title: "Leadership",
    icon: <BsPeople />,
    skills: ["Tech Speaking", "Project Management", "Community Building"],
    color: "bg-purple-400",
  },
];

function About() {
  return (
    <section className="bg-white py-20" id="about">
      <div className="container mx-auto px-4 max-w-6xl">
        <h2 className="text-4xl font-bold text-textDark mb-2">About Me</h2>
        <p className="text-gray-600 mb-16 text-lg">Dishant Gandhi is an AI/ML Consultant with over 5 years of experience specializing in Generative AI, Conversational AI, and LLMs. He has developed scalable chatbots, RAG pipelines, web applications, and AI-powered widgets, leveraging advanced tools like LangChain, Streamlit, and Kubernetes. With 20+ speaking sessions at global conferences, Dishant is known for simplifying complex AI concepts, driving innovation, and mentoring aspiring technologists to create impactful AI solutions.</p>

        {/* SKills Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-8">
          {skillCategories.map((category, idx) => (
            <div
              key={idx}
              className="bg-white p-8 rounded-2xl shadow-lg hover:shadow-xl transition-shadow"
            >
              <div className="flex items-start space-x-6">
                <div
                  className={`${category.color} p-4 rounded-full text-white text-2xl`}
                >
                  {category.icon}
                </div>
                <div className="flex-1">
                  <h3 className="text-2xl font-bold text-textDark mb-3">
                    {category.title}
                  </h3>
                  <p className="text-gray-600 text-sm leading-relaxed">
                    {category.skills.join(", ")}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default About;
