import React from "react";
import ProfileImage from "../assets/profile-pic.png";

const Hero = () => {
  return (
    <section className="pt-20 sm:pt-16 md:pt-24 bg-cream overflow-hidden" id="hero">
      <div className="container mx-auto px-4">
        <div className="flex flex-col md:flex-row items-center">
          
          <div className="md:w-1/2 mb-8 md:mb-0 text-center md:text-left">
            <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold mb-3 md:mb-4">
              Hey There, I'm <span className="text-teal-600">Dishant Gandhi</span>
            </h1>
            <p className="text-gray-600 text-base sm:text-lg mb-4 md:mb-6">
              Transforming Ideas into Intelligent Solutions with AI and Innovation
            </p>
            <p className="text-red-500 text-base sm:text-lg font-bold mb-6 md:mb-8">
              dishantg.official@gmail.com
            </p>
            <div className="flex items-center justify-center md:justify-start space-x-6 md:space-x-8">
              <div>
                <h2 className="text-3xl sm:text-3xl font-bold">
                  {new Date().getFullYear() - 2020}+
                </h2>
                <p className="text-gray-600 text-sm sm:text-base">Years Experience</p>
              </div>
              <div>
                <h2 className="text-2xl sm:text-3xl font-bold">20+</h2>
                <p className="text-gray-600 text-sm sm:text-base">Speaking Sessions</p>
              </div>
            </div>
          </div>

          {/* Right Column */}
          <div className="md:w-1/2 relative">
            <div className="relative flex justify-center py-4 md:py-8">
              <img
                src={ProfileImage}
                alt="Profile"
                className="mx-auto transform sm:scale-105 md:scale-125 translate-y-20"
                style={{ transform: 'translateY(7rem) scale(1.2)' }}
              />
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;