// src/pages/Blog.jsx
import React, { useEffect, useState, useMemo } from "react";
import { Link } from "react-router-dom";
import { fetchAllBlogs } from "../utils/blogFetchers";

const PAGE_TITLE = "Blogs";

export default function Blog() {
  const [items, setItems] = useState(null);
  const [loading, setLoading] = useState(true);
  const title = useMemo(() => PAGE_TITLE, []);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        setLoading(true);
        const data = await fetchAllBlogs();
        if (!alive) return;
        setItems(data);
      } catch (e) {
        console.error("Failed to load blogs:", e);
        if (alive) setItems([]);
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => { alive = false; };
  }, []);

  if (loading) {
    return (
      <section className="py-20 px-5 min-h-screen flex items-center justify-center bg-cream">
        <div className="text-lg text-lightText">Loading {title.toLowerCase()}…</div>
      </section>
    );
  }

  if (!items || items.length === 0) {
    return (
      <section className="pt-20 sm:pt-16 md:pt-24 py-16 px-4 bg-cream min-h-screen">
        <div className="max-w-3xl mx-auto text-center">
          <div className="mx-auto mb-6 h-32 w-32 rounded-full bg-gradient-to-br from-teal-100 to-cream grid place-items-center shadow-inner">
            <svg className="h-12 w-12 text-teal-600" viewBox="0 0 24 24" fill="none" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5"
                d="M4 19h16M4 5h16M8 5v14M16 5v14" />
            </svg>
          </div>
          <h1 className="text-3xl md:text-4xl font-bold text-darkText">{title}</h1>
          <p className="mt-3 text-lightText text-base md:text-lg">
            Blogs are in progress. Check back soon!
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="pt-20 sm:pt-16 md:pt-24 py-16 px-4 bg-cream min-h-screen">
      <div className="max-w-6xl mx-auto">
        <header className="text-center mb-10 sm:mb-14">
          <h1 className="text-3xl md:text-4xl font-bold text-darkText">{title}</h1>
          <p className="mt-3 text-lightText text-base md:text-lg">
            Latest articles from my blog, Medium, and guest posts
          </p>
        </header>

        <div className="grid gap-6 sm:gap-8 grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
          {items.map((it, idx) => (
            <Card key={it.url + it.title + idx} item={it} />
          ))}
        </div>
      </div>
    </section>
  );
}

function Card({ item }) {
  const isInternal = item.local && item.url?.startsWith("/blogs");
  
  // Determine source badge
  const sourceBadge = {
    cms: "Blog",
    medium: "Medium",
    langdb: "Guest Post"
  }[item.source] || "External";

  const Wrap = ({ children }) =>
    isInternal ? (
      <Link to={item.url} className="block focus:outline-none">{children}</Link>
    ) : (
      <a href={item.url} target="_blank" rel="noopener noreferrer" className="block focus:outline-none">
        {children}
      </a>
    );

  return (
    <article className="group bg-white rounded-xl shadow-lg hover:shadow-xl overflow-hidden transition-transform duration-300 hover:-translate-y-1">
      <Wrap>
        <div className="relative">
          {item.image && (
            <img
              src={item.image}
              alt={item.title}
              loading="lazy"
              className="w-full h-48 object-cover"
            />
          )}
          {/* Source badge overlay */}
          {item.external && (
            <div className="absolute top-2 right-2 bg-teal-600 text-white text-xs px-2 py-1 rounded-full shadow">
              {sourceBadge}
            </div>
          )}
        </div>
        <div className="p-5">
          <div className="flex items-center gap-2 text-[11px] uppercase text-teal-600">
            <span>{sourceBadge}</span>
            <span className="text-gray-300">•</span>
            <span className="text-gray-500">
              {item.created_at
                ? new Date(item.created_at).toLocaleDateString(undefined, {
                    year: "numeric",
                    month: "long",
                    day: "numeric",
                  })
                : ""}
            </span>
          </div>
          <h2 className="mt-2 text-xl font-semibold text-darkText group-hover:text-teal-600">
            {item.title}
          </h2>
          {item.excerpt && (
            <p className="mt-2 text-sm text-lightText line-clamp-3">{item.excerpt}</p>
          )}
          <div className="mt-3 flex flex-wrap gap-2">
            {(item.tags || []).slice(0, 3).map((t, i) => (
              <span
                key={t + i}
                className="inline-flex items-center rounded-md bg-cream px-2 py-0.5 text-xs text-darkText ring-1 ring-gray-200"
              >
                {t}
              </span>
            ))}
          </div>
          <div className="mt-4 inline-flex items-center text-teal-600 font-medium">
            <span className="text-sm">{item.external ? "Read on " + sourceBadge : "Read More"}</span>
            <svg
              className="w-4 h-4 ml-2 transition-transform duration-300 group-hover:translate-x-1"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
            </svg>
          </div>
        </div>
      </Wrap>
    </article>
  );
}
